const safe=(value)=>String(value).replace(/[<>]/g,"");
export const GENERATED_SHADER_NOTICE=`Generated by This Shader Does Not Exist (TSDNE).\nNo ownership, exclusivity, scarcity, or attribution requirement is asserted over this generated shader.\nTo the extent possible under law, this generated shader is dedicated to the public domain under CC0 1.0.\nYou may copy, modify, share, study, sell, and incorporate it into other works.`;
function vertex(){return `#version 300 es\nin vec2 a_position;\nvoid main(){gl_Position=vec4(a_position,0.0,1.0);}`;}
export function encounterRecord(c){return{schema:"tsdne-encounter-v1",id:c.id,createdAt:c.createdAt,family:c.family,seed:c.seed,origin:c.origin,parentId:c.parentId,model:c.model,mutation:c.mutation,graph:c.graph,perception:c.perception||null,source:c.source,notice:GENERATED_SHADER_NOTICE};}
export function rawGLSL(c){return `/*\n${GENERATED_SHADER_NOTICE}\nEncounter: ${c.id}\nFamily: ${c.family}\n*/\n${c.source}`;}
export function selfContainedHTML(c){const source=JSON.stringify(c.source),vs=JSON.stringify(vertex());return `<!doctype html>\n<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TSDNE ${safe(c.id.slice(0,12))}</title><style>html,body,canvas{width:100%;height:100%;margin:0;display:block;background:#000}</style><canvas></canvas><script>const canvas=document.querySelector('canvas'),gl=canvas.getContext('webgl2');if(!gl)throw Error('WebGL2 required');const compile=(t,s)=>{const x=gl.createShader(t);gl.shaderSource(x,s);gl.compileShader(x);if(!gl.getShaderParameter(x,gl.COMPILE_STATUS))throw Error(gl.getShaderInfoLog(x));return x};const p=gl.createProgram();gl.attachShader(p,compile(gl.VERTEX_SHADER,${vs}));gl.attachShader(p,compile(gl.FRAGMENT_SHADER,${source}));gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw Error(gl.getProgramInfoLog(p));const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);const pos=gl.getAttribLocation(p,'a_position'),res=gl.getUniformLocation(p,'u_resolution'),time=gl.getUniformLocation(p,'u_time'),motion=gl.getUniformLocation(p,'u_motion'),intensity=gl.getUniformLocation(p,'u_intensity'),start=performance.now();function frame(now){const d=Math.min(devicePixelRatio||1,2),w=Math.floor(innerWidth*d),h=Math.floor(innerHeight*d);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}gl.viewport(0,0,w,h);gl.useProgram(p);gl.enableVertexAttribArray(pos);gl.vertexAttribPointer(pos,2,gl.FLOAT,false,0,0);gl.uniform2f(res,w,h);gl.uniform1f(time,(now-start)/1000);if(motion)gl.uniform1f(motion,1);if(intensity)gl.uniform1f(intensity,1);gl.drawArrays(gl.TRIANGLES,0,3);requestAnimationFrame(frame)}requestAnimationFrame(frame);<\/script>`;}
export function threeJS(c){return `// ${GENERATED_SHADER_NOTICE.replaceAll("\n","\n// ")}\nimport * as THREE from 'three';\nconst material=new THREE.ShaderMaterial({uniforms:{u_resolution:{value:new THREE.Vector2()},u_time:{value:0},u_motion:{value:1},u_intensity:{value:1}},vertexShader:\`void main(){gl_Position=vec4(position,1.0);}\`,fragmentShader:${JSON.stringify(c.source.replace("#version 300 es\n",""))}});\n// Apply material to a full-screen plane and update the uniforms each frame.`;}
export function shaderToy(c){let body=c.source.replace(/^#version 300 es\n/,"").replace("out vec4 outColor;\n","").replace("uniform vec2 u_resolution;\n","#define u_resolution iResolution.xy\n").replace("uniform float u_time;\n","#define u_time iTime\n").replace("uniform float u_motion;\n","#define u_motion 1.0\n").replace("uniform float u_intensity;\n","#define u_intensity 1.0\n");body=body.replace(/void main\(\)\s*\{/,'void mainImage(out vec4 outColor, in vec2 fragCoord){').replaceAll("gl_FragCoord.xy","fragCoord");return `// ${GENERATED_SHADER_NOTICE.replaceAll("\n","\n// ")}\n${body}`;}
export function isf(c){const fragment=c.source.replace(/^#version 300 es\n/,"").replace("out vec4 outColor;\n","").replace("uniform vec2 u_resolution;\n","#define u_resolution RENDERSIZE\n").replace("uniform float u_time;\n","#define u_time TIME\n").replace("uniform float u_motion;\n","#define u_motion 1.0\n").replace("uniform float u_intensity;\n","#define u_intensity 1.0\n").replaceAll("outColor","gl_FragColor");return `/*{\"DESCRIPTION\":\"TSDNE encounter ${c.id}\",\"CREDIT\":\"CC0 — no exclusive ownership\",\"CATEGORIES\":[\"Generator\"],\"INPUTS\":[]}*/\n${fragment}`;}
export function exportFiles(c){return{[`tsdne-${c.id}.json`]:JSON.stringify(encounterRecord(c),null,2),[`tsdne-${c.id}.frag`]:rawGLSL(c),[`tsdne-${c.id}.html`]:selfContainedHTML(c),[`tsdne-${c.id}-three.js`]:threeJS(c),[`tsdne-${c.id}-shadertoy.glsl`]:shaderToy(c),[`tsdne-${c.id}.fs`]:isf(c)};}
export function downloadText(filename,text,type="text/plain"){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
